  return db.prepare(`SELECT id,project_id AS projectId,report_id AS reportId,photo_date AS photoDate,area,caption,file_ref AS fileRef,author,notes,original_filename AS originalFilename,stored_path AS storedPath,file_size AS fileSize,mime_type AS mimeType,uploaded_by_id AS uploadedById,uploaded_at AS uploadedAt FROM project_photos WHERE project_id=? ORDER BY photo_date DESC,id DESC`).all(projectId) as unknown as ProjectPhoto[];
